var WorktreeSetupSnapshot = Struct({
  threadId: ThreadId,
  phase: WorktreeSetupPhase,
  startedAt: IsoDateTime,
  endedAt: NullOr(IsoDateTime),
  branch: NullOr(TrimmedNonEmptyString),
  baseRef: NullOr(TrimmedNonEmptyString),
  worktreePath: NullOr(TrimmedNonEmptyString),
  /** Display name plus command of the setup script from t3.json, when one runs. */
  setupScript: NullOr(
    Struct({
      name: TrimmedNonEmptyString,
      command: TrimmedNonEmptyString,
      terminalId: TrimmedNonEmptyString
    })
  ),
  stages: ArraySchema(WorktreeSetupStage),
  /** Human readable reason when phase is failed. */
  error: NullOr(String6.check(isMaxLength(WORKTREE_SETUP_ERROR_MAX_LENGTH))),
  sequence: NonNegativeInt
});
var WorktreeSetupSubscribeInput = Struct({
  threadId: ThreadId
});
var WorktreeSetupStreamEvent = NullOr(WorktreeSetupSnapshot);
var WorktreeSetupCancelInput = Struct({
  threadId: ThreadId
});
var WorktreeSetupCancelResult = Struct({
  cancelled: Boolean3
});

